def bsearch(arr, target, low, high):
    if low > high: return -1
    mid = (low + high) // 2
    if arr[mid] == target: return mid
    if arr[mid] < target: return bsearch(arr, target, mid + 1, high)
    return bsearch(arr, target, low, mid - 1)
